    idle={2,true,{Track(0,{{0,Joint({0,1.15f,0})},{1,Joint({0,1.19f,0})},{2,Joint({0,1.15f,0})}}),Track(1,{{0,Joint({0,.73f,0},{0,-.08f,0})},{1,Joint({0,.73f,0},{0,.08f,0})},{2,Joint({0,.73f,0},{0,-.08f,0})}})}};
    walk={.8f,true,{Track(0,{{0,Joint({0,1.15f,0})},{.2f,Joint({0,1.2f,0})},{.4f,Joint({0,1.15f,0})},{.6f,Joint({0,1.2f,0})},{.8f,Joint({0,1.15f,0})}}),Track(2,{{0,Joint({-.48f,.18f,0},{.65f,0,0})},{.4f,Joint({-.48f,.18f,0},{-.65f,0,0})},{.8f,Joint({-.48f,.18f,0},{.65f,0,0})}}),Track(3,{{0,Joint({.48f,.18f,0},{-.65f,0,0})},{.4f,Joint({.48f,.18f,0},{.65f,0,0})},{.8f,Joint({.48f,.18f,0},{-.65f,0,0})}}),Track(4,{{0,Joint({-.2f,-.77f,0},{-.55f,0,0})},{.4f,Joint({-.2f,-.77f,0},{.55f,0,0})},{.8f,Joint({-.2f,-.77f,0},{-.55f,0,0})}}),Track(5,{{0,Joint({.2f,-.77f,0},{.55f,0,0})},{.4f,Joint({.2f,-.77f,0},{-.55f,0,0})},{.8f,Joint({.2f,-.77f,0},{.55f,0,0})}})}};
    attack={.48f,false,{Track(0,{{0,Joint({0,1.15f,0},{0,-.18f,0})},{.18f,Joint({0,1.15f,0},{0,.32f,0})},{.48f,Joint({0,1.15f,0})}}),Track(3,{{0,Joint({.48f,.18f,0},{-1.05f,0,-.2f})},{.18f,Joint({.48f,.18f,0},{.9f,0,.5f})},{.48f,Joint({.48f,.18f,0},{-.25f,0,0})}})}};
    creature.joints={{-1,Joint({0,.62f,0})},{0,Joint({0,.16f,.58f})},{0,Joint({-.4f,-.32f,.28f})},{0,Joint({.4f,-.32f,.28f})},{0,Joint({-.4f,-.32f,-.28f})},{0,Joint({.4f,-.32f,-.28f})}};
    creatureWalk={.65f,true,{Track(0,{{0,Joint({0,.62f,0})},{.325f,Joint({0,.68f,0})},{.65f,Joint({0,.62f,0})}}),Track(1,{{0,Joint({0,.16f,.58f},{.12f,0,0})},{.325f,Joint({0,.16f,.58f},{-.12f,0,0})},{.65f,Joint({0,.16f,.58f},{.12f,0,0})}}),Track(2,{{0,Joint({-.4f,-.32f,.28f},{-.45f,0,0})},{.325f,Joint({-.4f,-.32f,.28f},{.45f,0,0})},{.65f,Joint({-.4f,-.32f,.28f},{-.45f,0,0})}}),Track(3,{{0,Joint({.4f,-.32f,.28f},{.45f,0,0})},{.325f,Joint({.4f,-.32f,.28f},{-.45f,0,0})},{.65f,Joint({.4f,-.32f,.28f},{.45f,0,0})}}),Track(4,{{0,Joint({-.4f,-.32f,-.28f},{.45f,0,0})},{.325f,Joint({-.4f,-.32f,-.28f},{-.45f,0,0})},{.65f,Joint({-.4f,-.32f,-.28f},{.45f,0,0})}}),Track(5,{{0,Joint({.4f,-.32f,-.28f},{-.45f,0,0})},{.325f,Joint({.4f,-.32f,-.28f},{.45f,0,0})},{.65f,Joint({.4f,-.32f,-.28f},{-.45f,0,0})}})}};
